SELECT UTC_TIMESTAMP(3) AS observed_utc;
SELECT g.account_id,g.task_id,t.status task_status,g.group_execution_id,g.role_type,g.availability_status,g.occupied_at,g.released_at FROM pull_task_group_account g JOIN pull_task t ON t.id=g.task_id AND t.tenant_id=g.tenant_id WHERE g.account_id IN(43,1558,1572,1574,1719,1755) ORDER BY g.id;
SELECT 'marketing_account_occupancy' source,account_id,marketing_task_id,occupied_at FROM marketing_account_occupancy WHERE account_id IN(43,1558,1572,1574,1719,1755);
SELECT 'group_pull_marketing_execution' source,id,task_id,builder_account_id,marketing_account_id,execution_status,released_at FROM group_pull_marketing_execution WHERE (builder_account_id IN(43,1558,1572,1574,1719,1755) OR marketing_account_id IN(43,1558,1572,1574,1719,1755)) AND released_at IS NULL;
SELECT 'hyperlink_task_round_account' source,h.id,h.hyperlink_task_id,h.account_id,h.assignment_status,h.released_at,r.run_status FROM hyperlink_task_round_account h JOIN hyperlink_task_runtime r ON r.hyperlink_task_id=h.hyperlink_task_id WHERE h.account_id IN(43,1558,1572,1574,1719,1755) AND h.released_at IS NULL;
SELECT t.id,t.status,t.creation_mode,s.creator_group_id,s.manager_group_id,s.puller_group_id,s.station_group_id FROM pull_task t JOIN pull_task_standard_setting s ON s.task_id=t.id AND s.tenant_id=t.tenant_id WHERE t.deleted_at IS NULL AND t.status NOT IN('COMPLETED','ENDED') AND (s.creator_group_id IN(148,149,219) OR s.manager_group_id IN(148,149,219) OR s.puller_group_id IN(148,149,219) OR s.station_group_id IN(148,149,219));
SELECT UTC_TIMESTAMP(3) observed_utc;
SELECT a.id,a.ownership,c.cred_format FROM account a LEFT JOIN account_credential c ON c.account_id=a.id AND c.tenant_id=a.tenant_id AND c.deleted_at IS NULL WHERE a.id IN(43,1558,1572,1574,1719,1755);
SELECT 'feed' source,a.account_id,a.task_id,a.send_status,t.status,t.task_status,t.deleted_at FROM feed_task_account a JOIN feed_task t ON t.id=a.task_id AND t.tenant_id=a.tenant_id WHERE a.account_id IN(43,1558,1572,1574,1719,1755) ORDER BY a.id;
SELECT 'contact' source,a.account_id,a.task_id,a.state,t.is_enabled,t.run_status,t.deleted_at FROM contact_friend_task_account a JOIN contact_friend_task t ON t.id=a.task_id AND t.tenant_id=a.tenant_id WHERE a.account_id IN(43,1558,1572,1574,1719,1755) ORDER BY a.id;
SELECT 'join' source,a.account_id,a.join_task_id,a.status item_status,a.dispatch_state,t.status task_status,t.deleted_at FROM join_task_result a JOIN join_task t ON t.id=a.join_task_id AND t.tenant_id=a.tenant_id WHERE a.account_id IN(43,1558,1572,1574,1719,1755) ORDER BY a.id;
SELECT 'normal_group_creation' source,a.creator_account_id,a.task_id,a.status item_status,a.current_step,a.dispatch_status,t.status task_status,t.deleted_at FROM normal_group_creation_item a JOIN normal_group_creation_task t ON t.id=a.task_id AND t.tenant_id=a.tenant_id WHERE a.creator_account_id IN(43,1558,1572,1574,1719,1755) ORDER BY a.id;
SELECT 'group_creation_marketing' source,a.account_id,a.task_id,a.status item_status,t.status task_status,t.deleted_at FROM group_creation_marketing_item a JOIN group_creation_marketing_task t ON t.id=a.task_id AND t.tenant_id=a.tenant_id WHERE a.account_id IN(43,1558,1572,1574,1719,1755) ORDER BY a.id;
SELECT id,tenant_id,REGEXP_REPLACE(name,'[0-9]{8,}','[REDACTED]') name,REGEXP_REPLACE(remark,'[0-9]{8,}','[REDACTED]') remark,generation FROM group_data_package WHERE deleted_at IS NULL AND (name REGEXP '测试|受控|test|accept|验收|自有' OR remark REGEXP '测试|受控|test|accept|验收|自有') ORDER BY id DESC LIMIT 30;
SELECT id,tenant_id,REGEXP_REPLACE(package_name,'[0-9]{8,}','[REDACTED]') package_name,REGEXP_REPLACE(remark,'[0-9]{8,}','[REDACTED]') remark,phone_count FROM data_package WHERE deleted_at IS NULL AND (package_name REGEXP '测试|受控|test|accept|验收|自有' OR remark REGEXP '测试|受控|test|accept|验收|自有') ORDER BY id DESC LIMIT 30;
SELECT 'current_new_group_tasks' evidence,COUNT(*) task_count,MAX(id) max_id FROM pull_task WHERE creation_mode='NEW_GROUP' AND created_at >= 1790985600000;